/**
 * @method
 * @name validate
 * @description validate 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function (obj) {
    const arrVar = ['title', 'yyyymmdd', 'resoroomContn'];
    const fileVar = ['attachMovieSize', 'attachFile1Size', 'attachFile2Size', 'attachFile3Size', 'attachFile4Size', 'attachFile5Size'];
    if (!await scwin.isValid(obj, arrVar) || !await scwin.chkFileTotalSize(fileVar)) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name isValid
 * @description is Valid 처리
 * @param {Object} obj 컴포넌트
 * @param {*} arrVar arrVar
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isValid = async function (obj, arrVar) {
    for (scwin.i = 0; scwin.i < arrVar.length; scwin.i++) {
        const arrObj = (obj + '.' + arrVar[scwin.i]);
        if (arrObj.value === '') {
            await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(arrObj) + '(은)는 반드시 입력하셔야 합니다.');
            arrObj.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRData');
    const nr = await scwin.tx_fn_Search('/list/irData.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL21210.xml", { "method": 'searchIRData' });
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    $c.util.getComponent("dma_SearchReq").set("delChk", '');
    $c.util.getComponent('dma_SearchReq').set('wrtDdtm', $c.util.getComponent('cal_yyyymmdd').getValue()+ $c.util.getComponent('slc_hh').getValue() + $c.util.getComponent('slc_mi').getValue() + '00');
    if (scwin.movieCnt !== 0) {
        if ((String($c.util.getComponent('ipt_attachMovieChk').getValue() || "") !== "")) {
            $c.util.getComponent("dma_SearchReq").set("delChk", $c.util.getComponent("dma_SearchReq").get("delChk") + $c.util.getComponent('ipt_attachMovieChk').getValue()+ ',');
        } else {
            if ($c.util.getComponent("upd_attachMovie").getValue() !== '') {
                scwin.checkboxChk($c.util.fieldEl('ipt_attachMovieChk', 'attachMovieChk'));
                $c.util.getComponent("dma_SearchReq").set("delChk", $c.util.getComponent("dma_SearchReq").get("delChk") + $c.util.getComponent('ipt_attachMovieChk').getValue()+ ',');
            }
        }
    }
    for (scwin.i = 1; scwin.i < (scwin.realCnt - scwin.movieCnt + 1); scwin.i++) {
        if ((String($c.util.getComponent('document.irDataForm.attachFileChk' + scwin.i).getValue() || '') !== '')) {
            $c.util.getComponent("dma_SearchReq").set("delChk", $c.util.getComponent("dma_SearchReq").get("delChk") + $c.util.getComponent('document.irDataForm.attachFileChk' + scwin.i).getValue() + ',');
        } else {
            const elName = 'attachFile' + scwin.i;
            if ($c.util.getComponent(elName).getValue() !== '') {
                scwin.checkboxChk(document.irDataForm['attachFileChk' + scwin.i]);
                $c.util.getComponent("dma_SearchReq").set("delChk", $c.util.getComponent("dma_SearchReq").get("delChk") + $c.util.getComponent('document.irDataForm.attachFileChk' + scwin.i).getValue() + ',');
            }
        }
    }
    if ($c.util.getComponent("dma_SearchReq").get("delChk") !== '') {
        $c.util.getComponent("dma_SearchReq").set("delChk", ($c.util.getComponent("dma_SearchReq").get("delChk")).substr(0, $c.util.getComponent("dma_SearchReq").get("delChk").length - 1));
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'modifyIRData');
    if (await scwin.validate('document.irDataForm')) {
        if (await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = "개최일시"; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent('cal_yyyymmdd'))) {
            if (await $c.win.confirm("수정하시겠습니까?")) {
                const nr = await scwin.tx_fn_Modify();
                if (nr && nr.responseJSON && nr.responseJSON.success === true) {
                    $c.win.moveUrl("/ui/jsp/JLDFIL21212.xml", { "delChk": '', "method": 'modifyIRData' });
                }
            }
        } else {
            return;
        }
    } else {
        return;
    }
};

async function chkFile(obj) {
    if (obj.value === '') {
        return false;
    }
    const notFileType = ["js", "css", "html", "htm", "xml", "jsp", "asp", "php"];
    const fileFullNm = obj.value;
    const fileNm = fileFullNm.substring(fileFullNm.lastIndexOf("\\") + 1);
    const fileType = fileFullNm.substring(fileFullNm.lastIndexOf(".") + 1).toLowerCase();
    for (scwin.i = 0; scwin.i < notFileType.length; scwin.i++) {
        if (notFileType[scwin.i] === fileType) {
            await $c.win.alert("선택하신 파일(" + fileNm + ")에서 " + notFileType[scwin.i] + " 파일 확장자는 사용하실 수 없습니다.");
            ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
            return false;
        }
    }
    const fileSize = $c.cm.fn_getFileSize(fileFullNm);
    if (fileSize / 1024 > 30720) {
        await $c.win.alert("선택하신 " + fileNm + " 파일의 최대 크기는 30M를 넘을 수 없습니다.");
        ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
        return false;
    }
    $c.util.getComponent(obj.id + "Size").setValue(fileSize);
}

/**
 * @method
 * @name chkFileTotalSize
 * @description chk File Total Size 처리
 * @param {*} fileVar fileVar
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkFileTotalSize = async function (fileVar) {
    let totalSum = 0;
    for (let i = 0; i < fileVar.length; i++) {
        const attachFileSize = $c.util.getComponent(fileVar[i]).getValue();
        if (attachFileSize !== '') {
            totalSum = totalSum + (attachFileSize);
        }
    }
    if (totalSum / 1024 > 102400) {
        await $c.win.alert("첨부파일 및 동영상의 총 파일 크기는 100M를 넘을 수 없습니다. ");
        return false;
    }
    return true;
};

/**
 * @method
 * @name attachSizeReset
 * @description attach Size Reset 처리
 * @param {Object} obj 컴포넌트
 * @param {String} sizeId sizeId
 * @param {Number} size size
 * @returns {void}
 * @hidden N
 */
scwin.attachSizeReset = function (obj, sizeId, size) {
    if ($c.util.getComponent(obj.name.replace('Chk', '')).getValue() !== '') {
        return;
    }
    if (obj.checked) {
        $c.util.getComponent(sizeId).setValue(0);
    } else {
        $c.util.getComponent(sizeId).setValue(size);
    }
};

/**
 * @method
 * @name checkboxChk
 * @description checkbox Chk 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.checkboxChk = function (obj) {
    obj.checked = true;
    scwin.attachSizeReset(obj, obj.name.replace('Chk', '') + "Size", '');
};
